def move_part_materials(apps, schema_editor):
    """Материал и расход детали → первая позиция; слот из первой строки состава модели."""
    Part = apps.get_model("production", "Part")
    PartMaterial = apps.get_model("production", "PartMaterial")
    ModelPart = apps.get_model("production", "ModelPart")
    for part in Part.objects.all():
        slot = (
            ModelPart.objects.filter(part=part)
            .exclude(slot="")
            .order_by("pk")
            .values_list("slot", flat=True)
            .first()
            or ""
        )
        PartMaterial.objects.create(
            part=part,
            order=1,
            material_id=part.material_id,
            batch_qty=part.batch_material_qty,
            batch_unit=part.batch_material_unit,
            slot=slot,
        )


